import{U as e,gt as t,nt as n,rt as r}from"./chunks/framework.B3obAz7o.js";var i=JSON.parse(`{"title":"Deprecation policy","description":"","frontmatter":{},"headers":[],"relativePath":"deprecation.md","filePath":"deprecation.md","lastUpdated":1785249153000}`),a={name:`deprecation.md`};function o(e,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[r(`<h1 id="deprecation-policy" tabindex="-1">Deprecation policy <a class="header-anchor" href="#deprecation-policy" aria-label="Permalink to “Deprecation policy”">​</a></h1><p>This policy applies to the CLI, Node and WASM APIs, configuration files, diagnostic codes, generated file naming, and supported runtime behavior.</p><h2 id="_1-0-readiness-audit" tabindex="-1">1.0 readiness audit <a class="header-anchor" href="#_1-0-readiness-audit" aria-label="Permalink to “1.0 readiness audit”">​</a></h2><p>No API is eligible for removal in 1.0. The <code>0.x</code> line did not announce and carry an API through a complete deprecation window, so <code>1.0</code> retains every public item in <code>contracts/public-api.json</code>.</p><p>The Fontmin-compatible default export, the <code>glyph({ hinting })</code> alias for <code>preserveHinting</code>, and <code>ttf2woff2({ fallback })</code> runtime selection remain compatibility paths. They are not removed or silently changed. Future deprecation must start with the replacement-and-warning sequence below.</p><p>The machine-readable decision is recorded in <a href="https://github.com/fontmin-rs/fontmin-rs/blob/main/contracts/support.json" target="_blank" rel="noreferrer"><code>contracts/support.json</code></a>.</p><h2 id="before-1-0" tabindex="-1">Before 1.0 <a class="header-anchor" href="#before-1-0" aria-label="Permalink to “Before 1.0”">​</a></h2><p>The stable <code>0.x</code> public contract remains governed even though SemVer permits a minor release to make breaking changes. Every breaking change must:</p><ul><li>be called out under <code>Changed</code> or <code>Removed</code> in <code>CHANGELOG.md</code>;</li><li>include a concrete migration step in the relevant guide;</li><li>preserve an alias or compatibility path when doing so does not create a correctness or security risk.</li></ul><p>The stable <code>0.1</code> contract is frozen. A breaking change starts a new <code>0.x</code> minor line, uses its own prerelease validation cycle, and cannot ship in a patch release.</p><h2 id="after-1-0" tabindex="-1">After 1.0 <a class="header-anchor" href="#after-1-0" aria-label="Permalink to “After 1.0”">​</a></h2><p>Public behavior is not removed in a patch release. A planned removal follows this sequence:</p><ol><li>Introduce the replacement and document it.</li><li>Mark the old behavior deprecated in types and API documentation.</li><li>Emit a non-fatal warning where the CLI or configuration loader can identify the deprecated use reliably.</li><li>Keep both paths for at least one minor release.</li><li>Remove the old path only in a SemVer-major release.</li></ol><p>Security or data-corruption fixes may bypass the compatibility period. Such an exception requires a security advisory or prominent changelog rationale and a migration path when one exists.</p><h2 id="diagnostics" tabindex="-1">Diagnostics <a class="header-anchor" href="#diagnostics" aria-label="Permalink to “Diagnostics”">​</a></h2><p>Deprecation warnings go to stderr and must not corrupt JSON or binary stdout. Library calls do not write warnings implicitly; TypeScript annotations, documentation, and returned diagnostics carry the notice instead. Tests must cover the replacement and the compatibility path until removal.</p>`,16)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};